 * Splits a URI reference into its five generic-syntax components. Absent
 * components are `undefined`; the path is always a (possibly empty) string.
 */
export function parseReference(ref) {
  let rest = ref
  let scheme

  const stopIdx = (() => {
    for (let i = 0; i < rest.length; i++) {
      const c = rest[i]
      if (c === ':') return i
      if (c === '/' || c === '?' || c === '#') return -1
    }
    return -1
  })()
  if (stopIdx !== -1) {
    scheme = rest.slice(0, stopIdx)
    rest = rest.slice(stopIdx + 1)
  }

  let authority
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    let end = rest.length
    for (let i = 0; i < rest.length; i++) {
