    }
    authority = rest.slice(0, end)
    rest = rest.slice(end)
  }

  let end = rest.length
  for (let i = 0; i < rest.length; i++) {
    if (rest[i] === '?' || rest[i] === '#') { end = i; break }
  }
  const path = rest.slice(0, end)
  rest = rest.slice(end)

  let query
  if (rest.startsWith('?')) {
    let qend = rest.length
    for (let i = 1; i < rest.length; i++) {
      if (rest[i] === '#') { qend = i; break }
    }
    query = rest.slice(1, qend)
    rest = rest.slice(qend)
  }

  let fragment
  if (rest.startsWith('#')) {
    fragment = rest.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

/** Splits an authority into userinfo, host and port, per the task's rules. */
export function parseAuthority(authority) {
  let userinfo
  let hostport = authority
  const lastAt = authority.lastIndexOf('@')
  if (lastAt !== -1) {
    userinfo = authority.slice(0, lastAt)
    hostport = authority.slice(lastAt + 1)
  }

  const lastBracket = hostport.lastIndexOf(']')
  const searchStart = lastBracket + 1
  const colonIdx = hostport.indexOf(':', searchStart)

  let host
  let port
  if (colonIdx === -1) {
    host = hostport
  } else {
    host = hostport.slice(0, colonIdx)
    port = hostport.slice(colonIdx + 1)
  }

  return { userinfo, host, port }
