const UNRESERVED = /^[A-Za-z0-9\-._~]$/

/**
 * Uppercases every `%XX` triplet's hex digits and decodes those that encode
 * an unreserved character. Throws {@link TruncatedPercentEncodingError} when
 * a `%` lacks two following hex digits.
