import { parseReference, normalizeReference, resolveReference, TruncatedPercentEncodingError } from './uri.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  // eslint-disable-next-line no-constant-condition
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.slice(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function splitLines(text) {
  if (text === '') return []
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }
  return lines
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || (mode !== 'normalize' && mode !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
    return
  }

  const input = readStdin()
  const records = splitLines(input)
  const output = []

  for (let i = 0; i < records.length; i++) {
    const lineNo = i + 1
    const record = records[i]
    try {
      if (mode === 'normalize') {
        output.push(normalizeReference(record))
      } else {
        const spaceIdx = record.indexOf(' ')
        if (spaceIdx === -1) {
          fail(`line ${lineNo}: expected a base and a reference`)
          return
        }
        const baseStr = record.slice(0, spaceIdx)
        const refStr = record.slice(spaceIdx + 1)
        const base = parseReference(baseStr)
        if (base.scheme === undefined) {
          fail(`line ${lineNo}: the base has no scheme`)
          return
        }
        output.push(resolveReference(baseStr, refStr))
      }
    } catch (err) {
      if (err instanceof TruncatedPercentEncodingError) {
        fail(`line ${lineNo}: ${err.message}`)
        return
      }
      throw err
    }
  }

  process.stdout.write(output.map((line) => line + '\n').join(''))
  process.exit(0)
}

